tool_input.content:
# Prototype: strip heredoc bodies and quoted substrings from a shell command
# string so a command-position regex does not false-match literal text.
#
# Two passes, both line-oriented:
#  1. Heredoc body removal: once a `<<[-~]?QUOTE?DELIM QUOTE?` operator is
#     seen, every following line is dropped until a line consisting of
#     exactly DELIM (stripped of leading tabs for `<<-`) is found. That
#     terminator line is also dropped.
#  2. Quote stripping: within any line not inside a heredoc body, blank out
#     the interior of single-quoted and double-quoted substrings (double
#     quotes honor backslash-escaping; single quotes do not, per shell
#     rules), keeping the opening/closing quote characters so line
#     structure is still visible without carrying the literal text used for
#     command-position matching.

function strip_quotes(line,    i, n, c, out, j, depth) {
    out = ""
    i = 1
    n = length(line)
    while (i <= n) {
        c = substr(line, i, 1)
        if (c == "'") {
            j = index(substr(line, i + 1), "'")
            if (j == 0) {
                out = out c
                i++
            } else {
                out = out "''"
                i = i + 1 + j
            }
            continue
        }
        if (c == "\"") {
            j = i + 1
            while (j <= n) {
                if (substr(line, j, 1) == "\\" && j < n) {
                    j += 2
                    continue
                }
                if (substr(line, j, 1) == "\"") break
                j++
            }
            out = out "\"\""
            i = (j <= n) ? j + 1 : n + 1
            continue
        }
        out = out c
        i++
    }
    return out
}

BEGIN { in_heredoc = 0; delim = ""; strip_tabs = 0 }

{
    line = $0
    if (in_heredoc) {
        test = line
        if (strip_tabs) sub(/^\t+/, "", test)
        if (test == delim) {
            in_heredoc = 0
            delim = ""
            strip_tabs = 0
        }
        next
    }

    # Detect a heredoc operator: << or <<-, optional quote, word, optional
    # matching quote. Capture everything before it verbatim (it is real
    # command text), strip quotes from it, then record the delimiter.
    if (match(line, /<<-?[[:space:]]*(['"]?)[A-Za-z_][A-Za-z0-9_]*\1/)) {
        op = substr(line, RSTART, RLENGTH)
        before = substr(line, 1, RSTART - 1)
        after = substr(line, RSTART + RLENGTH)
        strip_tabs = (op ~ /^<<-/)
        delimword = op
        sub(/^<<-?[[:space:]]*/, "", delimword)
        gsub(/['"]/, "", delimword)
        delim = delimword
        in_heredoc = 1
        print strip_quotes(before) op strip_quotes(after)
        next
    }

    print strip_quotes(line)
}

